namespace {
bool stopped(const std::atomic<bool>* c){return c&&c->load();}
bool validTranscript(const MelodyTranscript& t){
    if(!std::isfinite(t.seconds)||t.seconds<=0||t.seconds>30||!std::isfinite(t.bpm)||t.bpm<30||t.bpm>300||t.seconds*t.bpm/60>64+1e-7||t.channel<0||t.channel>1||t.windows<1||t.voiced<0||t.voiced>t.windows||t.notes.empty()||t.notes.size()>maxNotesPerLane)return false;
    double previous=0;for(const auto& row:t.notes){const auto& n=row.note;if(!std::isfinite(row.confidence)||row.confidence<0||row.confidence>1||!std::isfinite(n.beat)||!std::isfinite(n.length)||n.beat<previous-1e-8||n.length<.01||n.beat+n.length>t.seconds*t.bpm/60+1e-7||n.pitch<0||n.pitch>127||!std::isfinite(n.velocity)||n.velocity<=0||n.velocity>1||n.probability!=1||n.ratchets!=1||n.conditionEvery!=1||n.conditionStep!=1)return false;previous=n.beat+n.length;}return true;
}
}
Result validateTranscription(const TranscriptionOptions& o){return std::isfinite(o.bpm)&&o.bpm>=30&&o.bpm<=300&&std::isfinite(o.gateDb)&&o.gateDb>=-72&&o.gateDb<=-6&&std::isfinite(o.confidence)&&o.confidence>=.65&&o.confidence<=.98&&std::isfinite(o.minMs)&&o.minMs>=40&&o.minMs<=500?Result::ok():Result::fail("Use project tempo 30-300, gate -72 to -6 dBFS, confidence 65-98% and minimum note 40-500 ms.");}
Result transcribeMelody(const AudioBuffer<float>& source,double rate,const TranscriptionOptions& options,MelodyTranscript& output,std::atomic<bool>* cancel,std::atomic<float>* progress){
    if(progress)progress->store(0);auto valid=validateTranscription(options);if(valid.failed())return valid;if(stopped(cancel))return Result::fail("Transcription cancelled.");
    if(!std::isfinite(rate)||rate<8000||rate>192000||source.getNumChannels()<1||source.getNumChannels()>2||source.getNumSamples()<rate*.12||source.getNumSamples()>rate*30||source.getNumSamples()/rate*options.bpm/60>64+1e-7)return Result::fail("Select 0.12-30 seconds that fit within 64 beats at the project tempo.");
    int channel=0;double best=0;for(int c=0;c<source.getNumChannels();++c){double mean=0,variance=0;for(int i=0;i<source.getNumSamples();++i){if((i&4095)==0&&stopped(cancel))return Result::fail("Transcription cancelled.");double v=source.getSample(c,i);if(!std::isfinite(v))return Result::fail("Source audio contains non-finite samples.");double delta=v-mean;mean+=delta/(i+1);variance+=delta*(v-mean);}if(variance>best){best=variance;channel=c;}}
    AudioBuffer<float> selected(2,source.getNumSamples());for(int c=0;c<2;++c)selected.copyFrom(c,0,source,channel,0,source.getNumSamples());AudioBuffer<float> audio;valid=resampleWave(selected,rate,12000,audio,[&]{return stopped(cancel);});if(valid.failed())return valid;
    constexpr int hop=120,n=768,maxLag=219,minLag=2,window=n+maxLag;constexpr double workingRate=12000;
    struct Frame{int pitch=-1;double confidence=0,power=0;};std::vector<Frame> frames;frames.reserve((size_t)(audio.getNumSamples()+hop-1)/hop);double maxPower=0,gate=std::pow(10.,options.gateDb/10);
    std::array<double,window> values;std::array<double,maxLag+1> difference{},normal{};
    for(int at=0;at<audio.getNumSamples();at+=hop){
        if(stopped(cancel))return Result::fail("Transcription cancelled.");double mean=0,power=0;for(int i=0;i<window;++i){double v=audio.getSample(0,jlimit(0,audio.getNumSamples()-1,at+i-window/2));values[(size_t)i]=v;double d=v-mean;mean+=d/(i+1);power+=d*(v-mean);}power/=window;Frame frame;frame.power=power;maxPower=jmax(maxPower,power);
        if(power>=gate){double cumulative=0;normal.fill(1);for(int lag=1;lag<=maxLag;++lag){if((lag&15)==0&&stopped(cancel))return Result::fail("Transcription cancelled.");double sum=0;for(int i=0;i<n;++i){double d=values[(size_t)i]-values[(size_t)(i+lag)];sum+=d*d;}difference[(size_t)lag]=sum;cumulative+=sum;normal[(size_t)lag]=cumulative>1e-20?sum*lag/cumulative:1;}
            int lag=0;for(int tau=minLag;tau<maxLag;++tau)if(normal[(size_t)tau]<=1-options.confidence){while(tau+1<maxLag&&normal[(size_t)tau+1]<normal[(size_t)tau])++tau;lag=tau;break;}
            if(lag>=minLag&&lag<maxLag){double a=difference[(size_t)lag-1],b=difference[(size_t)lag],c=difference[(size_t)lag+1],denom=a-2*b+c;double adjusted=lag+(std::abs(denom)>1e-20?jlimit(-.5,.5,.5*(a-c)/denom):0),hz=workingRate/adjusted;if(hz>=55&&hz<=1600){int pitch=(int)std::lround(69+12*std::log2(hz/440));if(pitch>=0&&pitch<=127){frame.pitch=pitch;frame.confidence=jlimit(0.,1.,1-normal[(size_t)lag]);}}}
        }
        frames.push_back(frame);if(progress)progress->store(.1f+.8f*(float)at/audio.getNumSamples());
    }
    // Bridge at most two unvoiced hops only when both sides agree. Three-hop
    // median voting removes isolated octave/semitone detections without inventing chords.
    auto corrected=frames;for(size_t i=0;i<frames.size();++i)if(frames[i].pitch<0){size_t end=i;while(end<frames.size()&&frames[end].pitch<0)++end;if(i>0&&end<frames.size()&&end-i<=2&&frames[i-1].pitch==frames[end].pitch)for(size_t j=i;j<end;++j){corrected[j]=frames[i-1];corrected[j].confidence=jmin(frames[i-1].confidence,frames[end].confidence);}i=end?end-1:end;}
    auto smooth=corrected;for(size_t i=1;i+1<corrected.size();++i)if(corrected[i-1].pitch>=0&&corrected[i-1].pitch==corrected[i+1].pitch&&corrected[i].pitch!=corrected[i-1].pitch)smooth[i]=corrected[i-1];
    MelodyTranscript next;next.seconds=source.getNumSamples()/rate;next.bpm=options.bpm;next.channel=channel;next.windows=(int)frames.size();for(const auto& f:frames)next.voiced+=f.pitch>=0;
    for(size_t i=0;i<smooth.size();){if(stopped(cancel))return Result::fail("Transcription cancelled.");if(smooth[i].pitch<0){++i;continue;}size_t end=i+1;double confidence=smooth[i].confidence,power=smooth[i].power;while(end<smooth.size()&&smooth[end].pitch==smooth[i].pitch){confidence+=smooth[end].confidence;power+=smooth[end].power;++end;}
        double start=jmax(0.,((double)i-.5)*hop/workingRate),finish=jmin(next.seconds,((double)end-.5)*hop/workingRate);if((finish-start)*1000+1e-6>=options.minMs){if(next.notes.size()>=maxNotesPerLane)return Result::fail("Transcription exceeds 512 notes. Select a shorter passage.");Note note;note.beat=start*options.bpm/60;note.length=(finish-start)*options.bpm/60;note.pitch=smooth[i].pitch;note.velocity=(float)jlimit(.1,.95,.9*std::sqrt(power/(end-i)/jmax(1e-20,maxPower)));next.notes.push_back({note,confidence/(end-i)});}i=end;
    }
    if(stopped(cancel))return Result::fail("Transcription cancelled.");if(next.notes.empty())return Result::fail("No stable melody notes found. Use a clean single-note line, lower the gate/confidence, or select longer notes.");if(!validTranscript(next))return Result::fail("Detected notes do not fit the supported pattern range.");output=std::move(next);if(progress)progress->store(1);return Result::ok();
}
Result appendTranscription(const Project& source,const MelodyTranscript& transcript,int track,const String& name,Project& output){
    if(!validTranscript(transcript))return Result::fail("Invalid or empty transcription.");if(track<0||track>=(int)source.tracks.size()||source.tracks[(size_t)track].isBus)return Result::fail("Choose an instrument channel for the detected notes.");if(source.patterns.size()>=maxPatterns)return Result::fail("All 32 patterns are in use. Free a pattern before transcription Apply.");if(std::abs(source.bpm-transcript.bpm)>1e-8)return Result::fail("Project tempo changed. Transcribe again.");
    Project next=source;Pattern p;p.name=name.trim().substring(0,80);if(p.name.isEmpty())p.name="Audio notes";p.length=jmin(64.,jmax(1.,std::ceil(transcript.seconds*transcript.bpm/60*4-1e-8)/4));p.lanes.resize(next.tracks.size());for(const auto& row:transcript.notes)p.lanes[(size_t)track].push_back(row.note);next.patterns.push_back(std::move(p));next.activePattern=(int)next.patterns.size()-1;next.songMode=false;Project checked;auto valid=projectFromJson(projectToJson(next),checked);if(valid.failed())return valid;output=std::move(next);return Result::ok();
}
String transcriptionSummary(const MelodyTranscript& t){String text=String((int)t.notes.size())+" estimated monophonic notes / "+String(t.seconds,3)+" seconds / "+String(t.bpm,3)+" BPM\nSelected stereo channel: "+String(t.channel+1)+" (highest AC energy)\nVoiced analysis windows: "+String(t.voiced)+" / "+String(t.windows)+"\n\nPitch    Beat    Length    Velocity    Periodicity\n";for(const auto& row:t.notes){const auto& n=row.note;text+=(row.confidence<.9?"? ":"  ")+samplerNoteName(n.pitch)+"    "+String(n.beat,3)+"    "+String(n.length,3)+"    "+String(n.velocity,2)+"    "+String(row.confidence*100,1)+"%\n";}text+="\n? marks periodicity below 90%. Periodicity is an estimate, not a guarantee of correct pitch. Timing is unquantized and relative to selection start; leading silence is retained. Relative RMS estimates velocity. Short attacks, bends, repeated same-pitch notes without a gap, noise, chords and mixed instruments can be missed or joined.\n\nOriginal auditions the selection. Notes preview uses the chosen channel in a temporary Pattern. Apply creates one new editable PAT pattern with one Undo, preserving existing notes/Playlist/audio. Inspect and correct notes in Piano roll; no drum or polyphonic transcription yet.";return text;}
var transcriptionToJson(const MelodyTranscript& t,const TranscriptionOptions& o,const File& file,const String& hash,int first,double rate){auto* v=new DynamicObject();v->setProperty("schema",1);v->setProperty("application","Pulse Studio audio to notes");v->setProperty("algorithm","pulse-yin-1 / 12 kHz / 10 ms hop / 55-1600 Hz");v->setProperty("sourcePath",file.getFullPathName());v->setProperty("sourceHash",hash);v->setProperty("sourceFirstFrame",first);v->setProperty("sourceRate",rate);v->setProperty("bpm",o.bpm);v->setProperty("gateDb",o.gateDb);v->setProperty("confidence",o.confidence);v->setProperty("minMs",o.minMs);v->setProperty("seconds",t.seconds);v->setProperty("channel",t.channel);v->setProperty("windows",t.windows);v->setProperty("voiced",t.voiced);Array<var> notes;for(const auto& row:t.notes){auto* n=new DynamicObject();n->setProperty("pitch",row.note.pitch);n->setProperty("beat",row.note.beat);n->setProperty("length",row.note.length);n->setProperty("velocity",row.note.velocity);n->setProperty("confidence",row.confidence);notes.add(var(n));}v->setProperty("notes",notes);v->setProperty("summary",transcriptionSummary(t));return var(v);}
Result saveTranscriptionReport(const File& target,const MelodyTranscript& t,const TranscriptionOptions& o,const File& source,const String& hash,int first,double rate){if(!validTranscript(t)||validateTranscription(o).failed()||std::abs(t.bpm-o.bpm)>1e-8||hash.length()!=64||first<0||!std::isfinite(rate)||rate<8000||rate>192000)return Result::fail("Invalid transcription report. Previous report retained.");auto text=JSON::toString(transcriptionToJson(t,o,source,hash,first,rate),false,22);if(text.getNumBytesAsUTF8()>1024*1024)return Result::fail("Transcription report exceeds 1 MiB.");auto valid=target.getParentDirectory().createDirectory();if(valid.failed())return valid;TemporaryFile temp(target);if(!temp.getFile().replaceWithText(text)||temp.getFile().loadFileAsString()!=text||!temp.overwriteTargetFileWithTemporary())return Result::fail("Cannot save transcription report. Previous report retained.");return Result::ok();}
void TranscriptionTask::run(){
    try{result=[&]()->Result{AssetFingerprint before,after;auto valid=fingerprintAssetFile(source,before,&cancel);if(valid.failed())return valid;
        AudioFormatManager formats;formats.registerBasicFormats();std::unique_ptr<AudioFormatReader> reader(formats.createReaderFor(source));if(!reader||reader->sampleRate!=sampleRate||reader->numChannels<1||reader->numChannels>2||sourceFirst<0||reader->lengthInSamples<sourceFirst+audio.getNumSamples())return Result::fail("Source audio changed. Reopen the waveform.");AudioBuffer<float> block(2,4096);
        for(int at=0;at<audio.getNumSamples();at+=4096){if(cancel.load())return Result::fail("Transcription cancelled.");int count=jmin(4096,audio.getNumSamples()-at);if(!reader->read(&block,0,count,sourceFirst+at,true,true))return Result::fail("Cannot verify source audio.");for(int c=0;c<2;++c)for(int i=0;i<count;++i)if(block.getSample(reader->numChannels==1?0:c,i)!=audio.getSample(c,at+i))return Result::fail("Source audio changed since opening. Reopen the waveform before transcription.");}
        valid=transcribeMelody(audio,sampleRate,options,transcript,&cancel,&progress);if(valid.failed())return valid;valid=fingerprintAssetFile(source,after,&cancel);if(valid.failed())return valid;if(before.hash!=after.hash||before.bytes!=after.bytes)return Result::fail("Source audio changed during transcription.");sourceHash=after.hash;sourceStamp=source.getFullPathName()+"|"+String(after.bytes)+"|"+String(after.modified);return Result::ok();}();}catch(const std::exception&){result=Result::fail("Not enough resources to transcribe audio.");}done.store(true,std::memory_order_release);
}
